import Testing
@testable import SafeBeautyCore

/// A differential test against the server's own implementation.
///
/// Three hundred randomly generated service layouts, run through
/// `functions/lib/slots.js` and pinned here with the answers it gave. The
/// hand-written cases in SlotsTests cover the rules someone thought to check;
/// this covers the combinations nobody would think to write down — a service
/// with 58 minutes of active time, 18 of processing and 54 more of active, on a
/// 30-minute grid, is not a case anyone invents.
///
/// If this file ever fails, the client and the server disagree about who is
/// sitting in which chair, and the right response is to find out why rather
/// than to regenerate the expectations.
///
/// Generated with a fixed seed, so the same 300 cases come back every time.
@Suite("Slot layout differential against the server")
struct SlotsDifferentialTests {

    typealias Case = (
        n: [String], t: [String: Slots.Timing], d: [String: Int],
        step: Int, span: Int, busy: [Int]
    )

    @Test("300 generated layouts match the server exactly")
    func differential() {
        var mismatches: [String] = []
        for c in Self.cases {
            let got = Slots.serviceLayout(
                serviceNames: c.n, timings: c.t,
                durationPerService: c.d, slotMinutes: c.step)
            if got.span != c.span || got.busyOffsets != c.busy {
                mismatches.append(
                    "step \(c.step) \(c.n) -> got span \(got.span) busy \(got.busyOffsets), "
                    + "server said span \(c.span) busy \(c.busy)")
            }
        }
        let summary = "\(mismatches.count) of \(Self.cases.count) disagreed:\n"
            + mismatches.prefix(5).joined(separator: "\n")
        #expect(mismatches.isEmpty, "\(summary)")
    }

    static let cases: [Case] = [
